`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        (PHYSICAL_UTILIZATION_REG < 0.00 || PHYSICAL_UTILIZATION_REG > 100.00)) begin
      $display("Error: [Unisim %s-2661] PHYSICAL_UTILIZATION attribute is set to %f.  Legal values for this attribute are 0.00 to 100.00. Instance: %m", MODULE_NAME, PHYSICAL_UTILIZATION_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((STANDARD_REG != "CUSTOM") &&
         (STANDARD_REG != "5GNR") &&
         (STANDARD_REG != "DOCSIS") &&
         (STANDARD_REG != "DVB_S2_X") &&
         (STANDARD_REG != "WIFI"))) begin
      $display("Error: [Unisim %s-2662] STANDARD attribute is set to %s.  Legal values for this attribute are CUSTOM, 5GNR, DOCSIS, DVB_S2_X or WIFI. Instance: %m", MODULE_NAME, STANDARD_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        (THROUGHPUT_UTILIZATION_REG < 0.00 || THROUGHPUT_UTILIZATION_REG > 100.00)) begin
      $display("Error: [Unisim %s-2663] THROUGHPUT_UTILIZATION attribute is set to %f.  Legal values for this attribute are 0.00 to 100.00. Instance: %m", MODULE_NAME, THROUGHPUT_UTILIZATION_REG);
      attr_err = 1'b1;
    end
    
    if (attr_err == 1'b1) #1 $finish;
  end
`endif



